import { withProjectBuildGradle, type ConfigPlugin } from 'expo/config-plugins';

/**
 * Pins every Android module to the NDK version Expo already chose.
 *
 * This lives in a config plugin because `android/` is generated by prebuild and
 * gitignored, so a hand-edit there does not survive.
 *
 * Expo's `expo-root-project` Gradle plugin sets `rootProject.ext.ndkVersion`
 * and `android/app/build.gradle` reads it — but native *library* modules
 * (`expo-updates` and anything else applying `com.android.library` with an
 * `externalNativeBuild`) never set it, so they fall back to AGP's own default.
 * That default is a different NDK revision, so Gradle downloads a second
 * multi-gigabyte NDK on every fresh machine and fails outright if that download
 * is ever interrupted, leaving a stub directory behind:
 *
 *   [CXX1101] NDK at .../ndk/<version> did not have a source.properties file
 *
 * One NDK for the whole build removes both problems.
 */

const MARKER = 'with-android-native-build.ts';

const NDK_VERSION_BLOCK = `
// Added by plugins/${MARKER} — pin every module to the NDK Expo already chose,
// so none of them falls back to AGP's default and pulls down a second NDK.
subprojects { subproject ->
  ['com.android.application', 'com.android.library'].each { pluginId ->
    subproject.plugins.withId(pluginId) {
      subproject.android {
        ndkVersion rootProject.ext.ndkVersion
      }
    }
  }
}
`;

const withAndroidNativeBuild: ConfigPlugin = (config) =>
  withProjectBuildGradle(config, (gradleConfig) => {
    if (gradleConfig.modResults.language !== 'groovy') {
      throw new Error(
        `Cannot pin ndkVersion: android/build.gradle is ${gradleConfig.modResults.language}, not groovy.`,
      );
    }

    if (!gradleConfig.modResults.contents.includes(MARKER)) {
      gradleConfig.modResults.contents += NDK_VERSION_BLOCK;
    }

    return gradleConfig;
  });

export default withAndroidNativeBuild;
